-        throw new NoSuchResourceException(e.getMessage());
-      }
-    }
-
-    // notify subscribers about the configuration changes
-    publisher.publish(new AmbariConfigurationChangedEvent(categoryName));
-    return getRequestStatus(null);
-  }
